import re, xml.etree.ElementTree as ET
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
W='{%s}'%ns['w']

# --- Document body with comment anchors ---
tree=ET.parse('word/document.xml'); root=tree.getroot()
out=[]
def text_of_para(p):
    # collect runs, note comment range starts/ends
    buf=[]
    for el in p.iter():
        tag=el.tag
        if tag==W+'t':
            buf.append(el.text or '')
        elif tag==W+'commentRangeStart':
            buf.append('  ⟦C%s→ '%el.get(W+'id'))
        elif tag==W+'commentRangeEnd':
            buf.append(' →C%s⟧'%el.get(W+'id'))
        elif tag==W+'tab':
            buf.append('\t')
    return ''.join(buf)

body=root.find(W+'body')
for p in body.iter(W+'p'):
    # style
    pPr=p.find(W+'pPr')
    style=''
    if pPr is not None:
        ps=pPr.find(W+'pStyle')
        if ps is not None: style=ps.get(W+'val')
    txt=text_of_para(p)
    if txt.strip() or style:
        prefix=('[%s] '%style) if style else ''
        out.append(prefix+txt)
print('\n'.join(out))
PY
